import React from 'react';

function Pricing() {
    return ( 
        <>
        <div  style={{ marginLeft: '5%' }} className='col-12 col-md-6 mb-4' >
        <h2  style={{ marginLeft: '3%' }}>Unbeatable pricing</h2>
         <p style={{ marginLeft: '3%' }}>We pioneered the concept of discount broking and price transparency in India. Flat fees and no hidden charges.</p>
        </div>

        <div className='col-12 col-md-6 mb-4' ></div>
        </>
     );
}

export default Pricing;
